    "내 삶의 중심은 언제나 체육관이었다. 그 과정에서 인간관계나 휴식은 자연스럽게 뒤로 밀려났지만, 특별히 슬프게 느끼지는 않았다. 자연스럽게 학교 친구들과의 관계는 멀어졌고, 새로운 관계는 대부분 운동하는 공간에서 만들어졌다. 사람을 만나는 기준마저 운동이 되었다. 함께 운동할 수 있는지, 좋은 파트너가 될 수 있는지가 중요했다. 약속도 대부분 운동 일정에 맞춰 결정되었다. 여자 친구와의 데이트가 있어도 중요한 세미나 때문에 체육관으로 향하거나, 한 달 약속을 운동 때문에 모두 취소하기도 했다. 이런 우선순위는 현재 체육관을 운영하는 지금까지도 크게 달라지지 않았다."
